func TestLines(t *testing.T){
 for _,limit:=range []int{1,2,4095,4096,65536,200000}{
  line:=strings.Repeat("a",limit)
  for _,tail:=range []string{"","\n"}{
   got,e:=Lines(tinyReader{strings.NewReader(line+"\nb"+tail)},limit)
   if e!=nil||!reflect.DeepEqual(got,[]string{line,"b"}){t.Fatal("legal boundary",limit,e)}
  }
  if _,e:=Lines(strings.NewReader(line+"x"),limit);e==nil{t.Fatal("over-limit accepted",limit)}
 }
 if _,e:=Lines(io.MultiReader(strings.NewReader("before\npartial"),brokenReader{}),100);e==nil{t.Fatal("read error hidden")}
 for _,limit:=range []int{0,-1}{if _,e:=Lines(strings.NewReader(""),limit);e==nil{t.Fatal("invalid limit")}}
