type oneShotReader struct{payload []byte;done bool}
func(r *oneShotReader)Read(p []byte)(int,error){
 if r.done{return 0,io.EOF}
 n:=copy(p,r.payload);r.payload=r.payload[n:]
 if len(r.payload)>0{return n,nil}
 r.done=true;return n,readFailure
}
