package exercise
import("time";"sync")
type item struct{v string;expires time.Time}
type Cache struct{mu sync.Mutex;now func()time.Time;m map[string]item}
func NewCache(now func()time.Time)*Cache{return &Cache{now:now,m:map[string]item{}}}
func(c *Cache)Put(k,v string,ttl time.Duration){c.mu.Lock();defer c.mu.Unlock();if ttl<=0{delete(c.m,k);return};c.m[k]=item{v,c.now().Add(ttl)}}
func(c *Cache)Get(k string)(string,bool){c.mu.Lock();defer c.mu.Unlock();x,ok:=c.m[k];if !ok{return "",false};if !c.now().Before(x.expires){delete(c.m,k);return "",false};return x.v,true}
func(c *Cache)Size()int{c.mu.Lock();defer c.mu.Unlock();n:=c.now();for k,x:=range c.m{if !n.Before(x.expires){delete(c.m,k)}};return len(c.m)}
```

定义Cache及NewCache(now func()time.Time)，Put(key,value string,ttl time.Duration)和Get(key)(string,bool)；ttl<=0删除键，now>=到期时缺失；更新重置TTL，Get过期同时回收；支持并发访问，Size返回清理过期后的键数。

