package exercise
import "net/netip"
type Route struct{Prefix,Next string}
func Lookup(rs []Route,a string)(string,bool,error){ip,e:=netip.ParseAddr(a);if e!=nil{return "",false,e};ip=ip.Unmap();best:=-1;next:="";for _,r:=range rs{p,e:=netip.ParsePrefix(r.Prefix);if e!=nil{return "",false,e};if p.Masked().Contains(ip)&&p.Bits()>best{best=p.Bits();next=r.Next}};return next,best>=0,nil}

