type Stack struct{mu sync.Mutex;fns []func()error;closed bool;err error}
func(s *Stack)Push(fn func()error)error{s.mu.Lock();defer s.mu.Unlock();if s.closed||fn==nil{return fmt.Errorf("closed or nil")};s.fns=append(s.fns,fn);return nil}
