package exercise
import("container/heap";"fmt")
type entry struct{id string;p int;seq uint64;idx int}
type entries []*entry
func(h entries)Len()int{return len(h)}
func(h entries)Less(i,j int)bool{if h[i].p!=h[j].p{return h[i].p<h[j].p};return h[i].seq<h[j].seq}
func(h entries)Swap(i,j int){h[i],h[j]=h[j],h[i];h[i].idx=i;h[j].idx=j}
func(h *entries)Push(v any){e:=v.(*entry);e.idx=len(*h);*h=append(*h,e)}
func(h *entries)Pop()any{v:=*h;e:=v[len(v)-1];*h=v[:len(v)-1];return e}
type Queue struct{h entries;m map[string]*entry;seq uint64}
func NewQueue()*Queue{return &Queue{m:map[string]*entry{}}}
func(q *Queue)Put(id string,p int)error{if id==""{return fmt.Errorf("id")};if e:=q.m[id];e!=nil{e.p=p;heap.Fix(&q.h,e.idx);return nil};q.seq++;e:=&entry{id:id,p:p,seq:q.seq};q.m[id]=e;heap.Push(&q.h,e);return nil}
func(q *Queue)Cancel(id string)bool{e:=q.m[id];if e==nil{return false};heap.Remove(&q.h,e.idx);delete(q.m,id);return true}
func(q *Queue)Pop()(string,bool){if len(q.h)==0{return "",false};e:=heap.Pop(&q.h).(*entry);delete(q.m,e.id);return e.id,true}
```

