package exercise
import("sync";"math";"fmt")
type Snapshot struct{Bounds []float64;Buckets []uint64;Count uint64;Sum float64}
type Histogram struct{mu sync.Mutex;s Snapshot}
func finite(v float64)bool{return !math.IsNaN(v)&&!math.IsInf(v,0)}
func NewHistogram(b []float64)(*Histogram,error){for i,v:=range b{if !finite(v)||i>0&&v<=b[i-1]{return nil,fmt.Errorf("bounds")}};return &Histogram{s:Snapshot{Bounds:append([]float64{},b...),Buckets:make([]uint64,len(b)+1)}},nil}
func(h *Histogram)Observe(v float64)error{if !finite(v){return fmt.Errorf("value")};h.mu.Lock();defer h.mu.Unlock();if h.s.Count==^uint64(0)||!finite(h.s.Sum+v){return fmt.Errorf("overflow")};for i,b:=range h.s.Bounds{if v<=b{h.s.Buckets[i]++}};h.s.Buckets[len(h.s.Bounds)]++;h.s.Count++;h.s.Sum+=v;return nil}
func(h *Histogram)Snapshot()Snapshot{h.mu.Lock();defer h.mu.Unlock();s:=h.s;s.Bounds=append([]float64{},s.Bounds...);s.Buckets=append([]uint64{},s.Buckets...);return s}
func(h *Histogram)Merge(s Snapshot)error{h.mu.Lock();defer h.mu.Unlock();if len(s.Bounds)!=len(h.s.Bounds)||len(s.Buckets)!=len(h.s.Buckets)||!finite(s.Sum)||s.Count>^uint64(0)-h.s.Count||!finite(s.Sum+h.s.Sum){return fmt.Errorf("shape")};for i,b:=range s.Bounds{if b!=h.s.Bounds[i]{return fmt.Errorf("bounds")}};for i,n:=range s.Buckets{if n>s.Count||i>0&&n<s.Buckets[i-1]{return fmt.Errorf("cumulative")}};if s.Buckets[len(s.Buckets)-1]!=s.Count{return fmt.Errorf("count")};for i,n:=range s.Buckets{h.s.Buckets[i]+=n};h.s.Count+=s.Count;h.s.Sum+=s.Sum;return nil}
```

定义Snapshot{Bounds []float64;Buckets []uint64;Count uint64;Sum float64}，NewHistogram(bounds)(*Histogram,error)、Observe(float64)error、Snapshot()Snapshot、Merge(Snapshot)error；bounds严格升序有限值，Buckets含+Inf累计桶；Observe拒绝NaN/Inf；Merge仅接受同bounds、累计单调且末桶=Count，失败不变；副本隔离并发安全。

