package exercise
import("encoding/json";"encoding/binary";"hash/crc32";"fmt")
type Op struct{Seq uint64;Key,Value string;Delete bool}
func Encode(v []Op)([]byte,error){out:=[]byte{};for i,x:=range v{if x.Seq!=uint64(i+1)||x.Key==""{return nil,fmt.Errorf("op")};b,e:=json.Marshal(x);if e!=nil||len(b)>4096{return nil,fmt.Errorf("length")};var h [4]byte;binary.BigEndian.PutUint32(h[:],uint32(len(b)));out=append(out,h[:]...);out=append(out,b...);binary.BigEndian.PutUint32(h[:],crc32.ChecksumIEEE(b));out=append(out,h[:]...)};return out,nil}
func Recover(b []byte)(map[string]string,int,error){m:=map[string]string{};pos:=0;seq:=uint64(1);for{if len(b)-pos<4{return m,pos,nil};n:=int(binary.BigEndian.Uint32(b[pos:pos+4]));if n>4096{return nil,pos,fmt.Errorf("length")};if len(b)-pos<8+n{return m,pos,nil};body:=b[pos+4:pos+4+n];if crc32.ChecksumIEEE(body)!=binary.BigEndian.Uint32(b[pos+4+n:pos+8+n]){return nil,pos,fmt.Errorf("crc")};var x Op;if json.Unmarshal(body,&x)!=nil||x.Seq!=seq||x.Key==""{return nil,pos,fmt.Errorf("op")};if x.Delete{delete(m,x.Key)}else{m[x.Key]=x.Value};seq++;pos+=8+n}}
```

