func(l *Leases)Renew(o string,t uint64,n,ttl int64)error{l.mu.Lock();defer l.mu.Unlock();if !l.clock(n)||ttl<=0||n>math.MaxInt64-ttl||!l.match(o,t,n){return fmt.Errorf("renew")};l.expiry=n+ttl;return nil}
