package exercise
import("crypto/sha256";"bytes";"sort";"fmt";"reflect";"sync")
type Node struct{ID,Zone string}
type Move struct{Key string;From,To []string}
type Placement struct{mu sync.RWMutex;rep int;epoch uint64;nodes []Node}
func NewPlacement(n int)(*Placement,error){if n<1{return nil,fmt.Errorf("replicas")};return &Placement{rep:n},nil}
func validate(ns []Node,rep int)error{ids,zones:=map[string]bool{},map[string]bool{};for _,n:=range ns{if n.ID==""||n.Zone==""||ids[n.ID]{return fmt.Errorf("node")};ids[n.ID]=true;zones[n.Zone]=true};if len(zones)<rep{return fmt.Errorf("zones")};return nil}
func(p *Placement)Update(e uint64,n []Node)error{p.mu.Lock();defer p.mu.Unlock();if e<=p.epoch{return fmt.Errorf("epoch")};if err:=validate(n,p.rep);err!=nil{return err};p.nodes=append([]Node{},n...);p.epoch=e;return nil}
func locate(k string,nodes []Node,rep int)([]string,error){if k==""||validate(nodes,rep)!=nil{return nil,fmt.Errorf("placement")};ns:=append([]Node{},nodes...);sort.Slice(ns,func(i,j int)bool{a:=sha256.Sum256([]byte(k+"\x00"+ns[i].ID));b:=sha256.Sum256([]byte(k+"\x00"+ns[j].ID));c:=bytes.Compare(a[:],b[:]);if c==0{return ns[i].ID<ns[j].ID};return c>0});zones:=map[string]bool{};out:=[]string{};for _,n:=range ns{if !zones[n.Zone]{zones[n.Zone]=true;out=append(out,n.ID);if len(out)==rep{break}}};return out,nil}
func(p *Placement)Locate(k string)([]string,error){p.mu.RLock();defer p.mu.RUnlock();return locate(k,p.nodes,p.rep)}
func(p *Placement)Plan(keys []string,ns []Node,e uint64)([]Move,error){p.mu.RLock();defer p.mu.RUnlock();if e<=p.epoch||validate(ns,p.rep)!=nil{return nil,fmt.Errorf("topology")};set:=map[string]bool{};for _,k:=range keys{if k==""{return nil,fmt.Errorf("key")};set[k]=true};ks:=[]string{};for k:=range set{ks=append(ks,k)};sort.Strings(ks);out:=[]Move{};for _,k:=range ks{from,err:=locate(k,p.nodes,p.rep);if err!=nil{return nil,err};to,_:=locate(k,ns,p.rep);if !reflect.DeepEqual(from,to){out=append(out,Move{k,from,to})}};return out,nil}
```

定义Node{ID,Zone string}及Move{Key string;From,To []string}；NewPlacement(replicas int)(*Placement,error)、Update(epoch uint64,nodes []Node)error、Locate(key string)([]string,error)、Plan(keys []string,next []Node,nextEpoch uint64)([]Move,error)。每副本必须不同Zone；节点ID/Zone非空、ID唯一，Zone数量>=replicas；Update epoch严格递增且校验失败不变。Locate按SHA256(key+NUL+nodeID)字节降序排名，hash相同ID升序，贪心取不同Zone；Plan不改变现有拓扑，只返回归属发生变化的去重键且按Key排序；不接受空key；输入输出复制。

